package com.osrsmarket.ledger;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import javax.inject.Singleton;

@Singleton
final class CostBasis
{
	private static final class Lot
	{
		int qty;
		final int costEach;

		Lot(int qty, int costEach)
		{
			this.qty = qty;
			this.costEach = costEach;
		}
	}

	private final Map<Integer, List<Lot>> lots = new HashMap<>();
	private final Map<Integer, Integer> lastAvg = new HashMap<>();

	synchronized void replaceAll(Map<Integer, int[]> positions)
	{
		lots.clear();
		if (positions == null)
		{
			return;
		}
		for (Map.Entry<Integer, int[]> e : positions.entrySet())
		{
			int itemId = e.getKey() == null ? 0 : e.getKey();
			int[] qc = e.getValue();
			if (itemId <= 0 || qc == null || qc.length < 2)
			{
				continue;
			}
			int qty = qc[0];
			int avgCost = qc[1];
			if (qty <= 0 || avgCost <= 0)
			{
				continue;
			}
			List<Lot> list = new ArrayList<>();
			list.add(new Lot(qty, avgCost));
			lots.put(itemId, list);
			lastAvg.put(itemId, avgCost);
		}
	}

	synchronized void addBuy(int itemId, int qty, int priceEach)
	{
		if (itemId <= 0 || qty <= 0 || priceEach <= 0)
		{
			return;
		}
		lots.computeIfAbsent(itemId, k -> new ArrayList<>()).add(new Lot(qty, priceEach));
		lastAvg.put(itemId, avgCost(itemId));
	}

	synchronized void addSell(int itemId, int qty)
	{
		if (itemId <= 0 || qty <= 0)
		{
			return;
		}
		int before = avgCost(itemId);
		if (before > 0)
		{
			lastAvg.put(itemId, before);
		}
		List<Lot> list = lots.get(itemId);
		if (list == null)
		{
			return;
		}
		int left = qty;
		Iterator<Lot> it = list.iterator();
		while (it.hasNext() && left > 0)
		{
			Lot lot = it.next();
			int take = Math.min(lot.qty, left);
			lot.qty -= take;
			left -= take;
			if (lot.qty <= 0)
			{
				it.remove();
			}
		}
		if (list.isEmpty())
		{
			lots.remove(itemId);
		}
		else
		{
			lastAvg.put(itemId, avgCost(itemId));
		}
	}

	synchronized int remaining(int itemId)
	{
		List<Lot> list = lots.get(itemId);
		if (list == null)
		{
			return 0;
		}
		int n = 0;
		for (Lot lot : list)
		{
			n += lot.qty;
		}
		return n;
	}

	synchronized int avgCost(int itemId)
	{
		List<Lot> list = lots.get(itemId);
		if (list == null || list.isEmpty())
		{
			return lastAvg.getOrDefault(itemId, 0);
		}
		long cost = 0;
		int qty = 0;
		for (Lot lot : list)
		{
			cost += (long) lot.qty * lot.costEach;
			qty += lot.qty;
		}
		return qty == 0 ? lastAvg.getOrDefault(itemId, 0) : (int) (cost / qty);
	}

	synchronized void clear()
	{
		lots.clear();
		lastAvg.clear();
	}
}

package com.osrsmarket.ledger;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.widgets.Widget;

/**
 * Reads completed offers from the in-game Grand Exchange History interface.
 * LIST is a flat 240-child widget: each trade is 6 leaves
 * (pad, pad, Bought/Sold, name, item icon, price).
 */
final class GeHistoryExtractor
{
	private static final Pattern DIGITS = Pattern.compile("(\\d[\\d,]*)");
	private static final Pattern EACH = Pattern.compile("([\\d,]+)\\s*(?:coins?\\s*)?each", Pattern.CASE_INSENSITIVE);
	private static final Pattern TAX_TOTAL = Pattern.compile("\\(([\\d,]+)\\s*-");
	private static final Pattern QTY_BEFORE_X = Pattern.compile("(\\d[\\d,]*)\\s*x\\b", Pattern.CASE_INSENSITIVE);
	private static final Pattern QTY_AFTER_X = Pattern.compile("\\bx\\s*(\\d[\\d,]*)\\b", Pattern.CASE_INSENSITIVE);
	private static final Pattern SIDE_ONLY = Pattern.compile("^(bought|sold)\\s*:?$", Pattern.CASE_INSENSITIVE);

	/** One dynamic child of the GE History list. */
	static final class Slot
	{
		final String text;
		final int itemId;
		final int itemQuantity;
		final boolean hidden;

		Slot(String text, int itemId, int itemQuantity)
		{
			this(text, itemId, itemQuantity, false);
		}

		Slot(String text, int itemId, int itemQuantity, boolean hidden)
		{
			this.text = text == null ? "" : text;
			this.itemId = itemId;
			this.itemQuantity = itemQuantity;
			this.hidden = hidden;
		}
	}

	static final class Fill
	{
		final int itemId;
		final String side;
		final int qty;
		final int priceEach;

		Fill(int itemId, String side, int qty, int priceEach)
		{
			this.itemId = itemId;
			this.side = side;
			this.qty = qty;
			this.priceEach = priceEach;
		}

		String tupleKey()
		{
			return itemId + ":" + side + ":" + qty + ":" + priceEach;
		}
	}

	private GeHistoryExtractor()
	{
	}

	static List<Fill> fromWidgets(Widget[] widgets)
	{
		return fromSlots(slotsFromWidgets(widgets));
	}

	static List<Fill> fromWidgetTree(Widget root)
	{
		return bestFromWidget(root, 0);
	}

	/**
	 * History rows are nested containers. Flattening the whole tree can put every
	 * "Sold" in one band and every price in another, so only the newest line matches.
	 * Prefer splitting child containers when that finds more fills.
	 */
	private static List<Fill> bestFromWidget(Widget w, int depth)
	{
		if (w == null || depth > 8)
		{
			return new ArrayList<>();
		}
		List<Fill> flat = fromSlots(slotsFromWidgetTree(w));
		List<Fill> split = new ArrayList<>();
		int sub = 0;
		for (Widget kid : childWidgets(w))
		{
			if (!widgetHasKids(kid))
			{
				continue;
			}
			sub++;
			split.addAll(bestFromWidget(kid, depth + 1));
		}
		if (sub == 0 || split.size() <= flat.size())
		{
			return flat;
		}
		return split;
	}

	static List<Fill> fromRowGroups(List<List<Slot>> groups)
	{
		List<Fill> split = new ArrayList<>();
		if (groups == null)
		{
			return split;
		}
		List<Slot> flat = new ArrayList<>();
		for (List<Slot> group : groups)
		{
			if (group == null)
			{
				continue;
			}
			split.addAll(fromSlots(group));
			flat.addAll(group);
		}
		List<Fill> flattened = fromSlots(flat);
		return split.size() > flattened.size() ? split : flattened;
	}

	private static Widget[] childWidgets(Widget w)
	{
		List<Widget> out = new ArrayList<>();
		addChildren(out, nestedChildren(w));
		addChildren(out, w.getDynamicChildren());
		addChildren(out, w.getStaticChildren());
		return out.toArray(new Widget[0]);
	}

	private static void addChildren(List<Widget> out, Widget[] widgets)
	{
		if (widgets == null)
		{
			return;
		}
		for (Widget w : widgets)
		{
			if (w != null)
			{
				out.add(w);
			}
		}
	}

	private static boolean widgetHasKids(Widget w)
	{
		return len(nestedChildren(w)) > 0
			|| len(w.getDynamicChildren()) > 0
			|| len(w.getStaticChildren()) > 0;
	}

	static List<Slot> slotsFromWidgetTree(Widget root)
	{
		List<Slot> rows = new ArrayList<>();
		collectWidget(root, rows);
		return rows;
	}

	static List<Slot> slotsFromWidgets(Widget[] widgets)
	{
		List<Slot> rows = new ArrayList<>();
		collectArray(widgets, rows);
		return rows;
	}

	static String debugSlots(List<Slot> rows, int limit)
	{
		if (rows == null || rows.isEmpty())
		{
			return "total=0";
		}
		StringBuilder sb = new StringBuilder();
		int n = Math.min(Math.max(0, limit), rows.size());
		for (int i = 0; i < n; i++)
		{
			Slot s = rows.get(i);
			String t = plain(s.text);
			if (t.length() > 36)
			{
				t = t.substring(0, 36) + "…";
			}
			sb.append(i).append(":{id=").append(s.itemId)
				.append(" q=").append(s.itemQuantity)
				.append(" t=").append(t).append("} ");
		}
		sb.append("total=").append(rows.size());
		return sb.toString();
	}

	static String debugFills(List<Fill> fills)
	{
		if (fills == null || fills.isEmpty())
		{
			return "fills=0";
		}
		StringBuilder sb = new StringBuilder();
		sb.append("fills=").append(fills.size());
		int n = Math.min(fills.size(), 40);
		for (int i = 0; i < n; i++)
		{
			Fill f = fills.get(i);
			sb.append(" [").append(i).append("] ")
				.append(f.side)
				.append(" id=").append(f.itemId)
				.append(" q=").append(f.qty)
				.append(" @").append(f.priceEach);
		}
		return sb.toString();
	}

	/** One-shot dump of LIST children so we can see why only one History row parses. */
	static String debugLayout(Widget root)
	{
		if (root == null)
		{
			return "root=null";
		}
		StringBuilder sb = new StringBuilder();
		sb.append("root dyn=").append(len(root.getDynamicChildren()))
			.append(" nest=").append(len(nestedChildren(root)))
			.append(" stat=").append(len(root.getStaticChildren()))
			.append(" hidden=").append(root.isHidden());
		Widget[] kids = childWidgets(root);
		sb.append(" kids=").append(kids.length);
		int n = Math.min(kids.length, 20);
		for (int i = 0; i < n; i++)
		{
			Widget k = kids[i];
			List<Slot> slots = slotsFromWidgetTree(k);
			List<Fill> fills = fromSlots(slots);
			sb.append("\n kid").append(i)
				.append(" type=").append(k.getType())
				.append(" dyn=").append(len(k.getDynamicChildren()))
				.append(" nest=").append(len(nestedChildren(k)))
				.append(" stat=").append(len(k.getStaticChildren()))
				.append(" hidden=").append(k.isHidden())
				.append(" slots=").append(slots.size())
				.append(" fills=").append(fills.size())
				.append(" ").append(debugSlots(slots, 10));
		}
		sb.append("\nflat ").append(debugSlots(slotsFromWidgetTree(root), 48));
		sb.append("\ntree ").append(debugTree(root, 0, 3, 80, new int[] {0}));
		return sb.toString();
	}

	private static String debugTree(Widget w, int depth, int maxDepth, int maxNodes, int[] count)
	{
		if (w == null || depth > maxDepth || count[0] >= maxNodes)
		{
			return "";
		}
		count[0]++;
		String t = plain(w.getText());
		if (t.length() > 28)
		{
			t = t.substring(0, 28) + "…";
		}
		StringBuilder sb = new StringBuilder();
		sb.append(depth).append(":{ty=").append(w.getType())
			.append(" id=").append(w.getItemId())
			.append(" q=").append(w.getItemQuantity())
			.append(" d=").append(len(w.getDynamicChildren()))
			.append(" n=").append(len(nestedChildren(w)))
			.append(" s=").append(len(w.getStaticChildren()))
			.append(" t=").append(t).append("} ");
		for (Widget kid : childWidgets(w))
		{
			sb.append(debugTree(kid, depth + 1, maxDepth, maxNodes, count));
		}
		return sb.toString();
	}

	private static void collectArray(Widget[] widgets, List<Slot> rows)
	{
		if (widgets == null)
		{
			return;
		}
		for (Widget w : widgets)
		{
			collectWidget(w, rows);
		}
	}

	private static void collectWidget(Widget w, List<Slot> rows)
	{
		if (w == null)
		{
			return;
		}
		Widget[] nested = nestedChildren(w);
		Widget[] dyn = w.getDynamicChildren();
		Widget[] stat = w.getStaticChildren();
		boolean hasKids = len(nested) > 0 || len(dyn) > 0 || len(stat) > 0;
		if (!hasKids)
		{
			rows.add(toSlot(w));
			return;
		}
		if (hasLeafContent(w))
		{
			rows.add(toSlot(w));
		}
		collectArray(nested, rows);
		collectArray(dyn, rows);
		collectArray(stat, rows);
	}

	private static Widget[] nestedChildren(Widget w)
	{
		try
		{
			return w.getNestedChildren();
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static int len(Widget[] widgets)
	{
		if (widgets == null)
		{
			return 0;
		}
		int n = 0;
		for (Widget w : widgets)
		{
			if (w != null)
			{
				n++;
			}
		}
		return n;
	}

	private static boolean hasLeafContent(Widget w)
	{
		if (w.getItemId() > 0)
		{
			return true;
		}
		return !plain(w.getText()).isEmpty();
	}

	private static Slot toSlot(Widget w)
	{
		return new Slot(w.getText(), w.getItemId(), w.getItemQuantity(), w.isHidden());
	}

	static List<Fill> fromSlots(List<Slot> rows)
	{
		if (rows == null || rows.isEmpty())
		{
			return new ArrayList<>();
		}
		if (looksLikeJagexHistory(rows))
		{
			List<Fill> strided = new ArrayList<>();
			for (int i = 0; i + 6 <= rows.size(); i += 6)
			{
				Fill fill = fromJagexGroup(rows.subList(i, i + 6));
				if (fill != null)
				{
					strided.add(fill);
				}
			}
			if (!strided.isEmpty())
			{
				return strided;
			}
		}
		return matchWalking(rows);
	}

	private static boolean looksLikeJagexHistory(List<Slot> rows)
	{
		if (rows.size() < 6 || rows.size() % 6 != 0)
		{
			return false;
		}
		return parseSide(plain(rows.get(2).text)) != null;
	}

	/**
	 * Live History row: pad, pad, Bought/Sold, name, icon, price.
	 * Leftover empty or hidden slots must not become a fill.
	 */
	private static Fill fromJagexGroup(List<Slot> group)
	{
		if (group == null || group.size() != 6)
		{
			return null;
		}
		for (int i = 2; i <= 5; i++)
		{
			if (group.get(i).hidden)
			{
				return null;
			}
		}
		String side = parseSide(plain(group.get(2).text));
		if (side == null)
		{
			return null;
		}
		String nameText = plain(group.get(3).text);
		if (nameText.isEmpty() || parseSide(nameText) != null || looksLikePrice(nameText))
		{
			return null;
		}
		Slot item = group.get(4);
		if (item.itemId <= 0)
		{
			return null;
		}
		if (!looksLikePrice(group.get(5).text))
		{
			return null;
		}
		int namedQty = qtyInName(nameText);
		int qty = namedQty > 0 ? namedQty : item.itemQuantity;
		if (qty <= 0)
		{
			return null;
		}
		if (namedQty > 0 && item.itemQuantity > 1 && namedQty != item.itemQuantity)
		{
			return null;
		}
		int price = priceEach(plain(group.get(5).text), qty);
		if (price <= 0)
		{
			return null;
		}
		return new Fill(item.itemId, side, qty, price);
	}

	private static List<Fill> matchWalking(List<Slot> rows)
	{
		List<Fill> out = new ArrayList<>();
		for (int i = 0; i < rows.size(); )
		{
			Match match = matchAt(rows, i);
			if (match != null)
			{
				out.add(match.fill);
				i = Math.max(i + 1, match.end);
			}
			else
			{
				i++;
			}
		}
		return out;
	}

	private static String nearbyName(List<Slot> rows, int from, int to, int step)
	{
		if (step == 0)
		{
			return "";
		}
		for (int j = from; step > 0 ? j <= to : j >= to; j += step)
		{
			if (j < 0 || j >= rows.size())
			{
				break;
			}
			String t = plain(rows.get(j).text);
			if (t.isEmpty())
			{
				continue;
			}
			if (parseSide(t) != null)
			{
				if (step > 0)
				{
					break;
				}
				continue;
			}
			if (looksLikePrice(t))
			{
				continue;
			}
			return t;
		}
		return "";
	}

	private static final class Match
	{
		final Fill fill;
		final int end;

		Match(Fill fill, int end)
		{
			this.fill = fill;
			this.end = end;
		}
	}

	/**
	 * Live GE History is Bought/Sold then name then icon then price. Older
	 * layouts put the name behind Sold; leftover Sold sprites still need a name.
	 */
	private static Match matchAt(List<Slot> rows, int sideIdx)
	{
		String side = parseSide(plain(rows.get(sideIdx).text));
		if (side == null)
		{
			return null;
		}
		String nameText = nearbyName(rows, sideIdx + 1, Math.min(rows.size() - 1, sideIdx + 4), 1);
		if (nameText.isEmpty())
		{
			nameText = nearbyName(rows, sideIdx - 1, Math.max(0, sideIdx - 3), -1);
		}
		if (nameText.isEmpty())
		{
			return null;
		}
		Slot item = null;
		int itemIdx = -1;
		String priceText = "";
		int priceIdx = -1;
		int last = Math.min(rows.size() - 1, sideIdx + 6);
		for (int j = sideIdx + 1; j <= last; j++)
		{
			Slot s = rows.get(j);
			if (item == null && s.itemId > 0)
			{
				item = s;
				itemIdx = j;
			}
			if (priceIdx < 0 && looksLikePrice(s.text))
			{
				priceText = plain(s.text);
				priceIdx = j;
			}
			if (item != null && priceIdx >= 0)
			{
				break;
			}
		}
		if (item == null || priceIdx < 0)
		{
			return null;
		}
		int namedQty = qtyInName(nameText);
		int qty = namedQty > 0 ? namedQty : item.itemQuantity;
		if (qty <= 0)
		{
			return null;
		}
		if (namedQty > 0 && item.itemQuantity > 1 && namedQty != item.itemQuantity)
		{
			return null;
		}
		int price = priceEach(priceText, qty);
		if (price <= 0)
		{
			return null;
		}
		int end = Math.max(itemIdx, priceIdx) + 1;
		return new Match(new Fill(item.itemId, side, qty, price), end);
	}

	/** History is newest-first; reverse so FIFO lots land in trade order. */
	static List<Fill> oldestFirst(List<Fill> newestFirst)
	{
		List<Fill> out = new ArrayList<>(newestFirst.size());
		for (int i = newestFirst.size() - 1; i >= 0; i--)
		{
			out.add(newestFirst.get(i));
		}
		return out;
	}

	static int qtyFromName(String text, int iconQty)
	{
		int named = qtyInName(text);
		return named > 0 ? named : iconQty;
	}

	static int qtyInName(String text)
	{
		String t = plain(text);
		Matcher after = QTY_AFTER_X.matcher(t);
		if (after.find())
		{
			long n = parseNumber(after.group(1));
			if (n > 0 && n <= Integer.MAX_VALUE)
			{
				return (int) n;
			}
		}
		Matcher before = QTY_BEFORE_X.matcher(t);
		if (before.find())
		{
			long n = parseNumber(before.group(1));
			if (n > 0 && n <= Integer.MAX_VALUE)
			{
				return (int) n;
			}
		}
		return 0;
	}

	static boolean looksLikePrice(String text)
	{
		String t = plain(text).toLowerCase();
		if (t.isEmpty())
		{
			return false;
		}
		return t.contains("each") || t.contains("coin") || (t.contains("(") && t.contains("-"));
	}

	static String parseSide(String text)
	{
		String t = plain(text);
		if (t.isEmpty())
		{
			return null;
		}
		Matcher m = SIDE_ONLY.matcher(t);
		if (!m.matches())
		{
			return null;
		}
		return t.toLowerCase().startsWith("bought") ? "buy" : "sell";
	}

	static int priceEach(String text, int qty)
	{
		String t = plain(text);
		if (t.isEmpty() || qty <= 0)
		{
			return 0;
		}
		Matcher tax = TAX_TOTAL.matcher(t);
		if (tax.find())
		{
			long total = parseNumber(tax.group(1));
			return total > 0 ? (int) (total / qty) : 0;
		}
		Matcher each = EACH.matcher(t);
		if (each.find())
		{
			return (int) parseNumber(each.group(1));
		}
		Matcher digits = DIGITS.matcher(t);
		if (digits.find())
		{
			long n = parseNumber(digits.group(1));
			if (n <= 0)
			{
				return 0;
			}
			if (qty > 1 && n % qty == 0 && n > qty)
			{
				return (int) (n / qty);
			}
			return (int) n;
		}
		return 0;
	}

	static String plain(String text)
	{
		if (text == null)
		{
			return "";
		}
		return text.replaceAll("<[^>]+>", " ").replace('\u00a0', ' ').replaceAll("\\s+", " ").trim();
	}

	private static long parseNumber(String raw)
	{
		if (raw == null)
		{
			return 0;
		}
		StringBuilder s = new StringBuilder();
		for (int i = 0; i < raw.length(); i++)
		{
			char c = raw.charAt(i);
			if (c >= '0' && c <= '9')
			{
				s.append(c);
			}
		}
		if (s.length() == 0)
		{
			return 0;
		}
		try
		{
			return Long.parseLong(s.toString());
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}
}

package com.osrsmarket.ledger;

import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;

/**
 * Puts an item on the GE "Previous search" / quick-select row
 * (the same slot that remembers Masori mask after you search it).
 */
final class GeLastSearch
{
	private GeLastSearch()
	{
	}

	static boolean isSearchTitle(String title)
	{
		if (title == null)
		{
			return false;
		}
		String plain = title.replaceAll("<[^>]*>", "");
		return plain.contains("What would you like to buy?")
			|| plain.contains("What would you like to sell?");
	}

	static void prime(Client client, int itemId)
	{
		int id = unnoted(client, itemId);
		if (id <= 0)
		{
			return;
		}
		int[] varps = client.getVarps();
		if (varps == null || VarPlayerID.GE_LAST_SEARCHED >= varps.length)
		{
			return;
		}
		varps[VarPlayerID.GE_LAST_SEARCHED] = id;
		try
		{
			client.queueChangedVarp(VarPlayerID.GE_LAST_SEARCHED);
		}
		catch (RuntimeException ignored)
		{
			/* older clients still keep the varp write */
		}
		if (!searchOpen(client))
		{
			return;
		}
		rebuild(client);
		paint(client, id);
	}

	private static int unnoted(Client client, int itemId)
	{
		if (itemId <= 0)
		{
			return -1;
		}
		try
		{
			ItemComposition def = client.getItemDefinition(itemId);
			if (def != null && def.getNote() != -1)
			{
				int linked = def.getLinkedNoteId();
				if (linked > 0)
				{
					return linked;
				}
			}
		}
		catch (RuntimeException ignored)
		{
			return itemId;
		}
		return itemId;
	}

	private static boolean searchOpen(Client client)
	{
		Widget title = client.getWidget(InterfaceID.Chatbox.MES_TEXT);
		if (title == null || title.isHidden())
		{
			return false;
		}
		return isSearchTitle(title.getText());
	}

	private static void rebuild(Client client)
	{
		Widget contents = client.getWidget(InterfaceID.Chatbox.MES_LAYER_SCROLLCONTENTS);
		if (run(client, contents != null ? contents.getOnLoadListener() : null))
		{
			return;
		}
		if (contents != null && run(client, contents.getOnVarTransmitListener()))
		{
			return;
		}
		Widget layer = client.getWidget(InterfaceID.Chatbox.MES_LAYER);
		if (run(client, layer != null ? layer.getOnLoadListener() : null))
		{
			return;
		}
		try
		{
			client.runScript(
				ScriptID.GE_ITEM_SEARCH,
				InterfaceID.Chatbox.MES_LAYER_SCROLLCONTENTS,
				InterfaceID.Chatbox.MES_LAYER_SCROLLBAR,
				0);
		}
		catch (RuntimeException ignored)
		{
			/* search widgets vary by client revision */
		}
	}

	private static boolean run(Client client, Object[] listener)
	{
		if (listener == null || listener.length == 0)
		{
			return false;
		}
		try
		{
			client.runScript(listener);
			return true;
		}
		catch (RuntimeException e)
		{
			return false;
		}
	}

	private static void paint(Client client, int itemId)
	{
		Widget contents = client.getWidget(InterfaceID.Chatbox.MES_LAYER_SCROLLCONTENTS);
		if (contents == null)
		{
			return;
		}
		String name;
		try
		{
			ItemComposition def = client.getItemDefinition(itemId);
			name = def == null ? null : def.getName();
		}
		catch (RuntimeException e)
		{
			return;
		}
		if (name == null || name.isEmpty() || "null".equalsIgnoreCase(name))
		{
			return;
		}
		paintKids(contents.getDynamicChildren(), itemId, name);
		paintKids(contents.getStaticChildren(), itemId, name);
	}

	private static void paintKids(Widget[] kids, int itemId, String name)
	{
		if (kids == null)
		{
			return;
		}
		boolean row = false;
		for (Widget kid : kids)
		{
			if (kid == null)
			{
				continue;
			}
			String text = kid.getText();
			if (text != null && text.contains("Previous search"))
			{
				row = true;
				continue;
			}
			if (!row)
			{
				continue;
			}
			if (text != null && text.contains("Start typing"))
			{
				break;
			}
			if (kid.getType() == WidgetType.GRAPHIC || kid.getItemId() > 0)
			{
				kid.setItemId(itemId);
				kid.setItemQuantity(1);
				kid.setHidden(false);
				continue;
			}
			if (text != null && !text.isEmpty() && !text.contains("Previous search"))
			{
				kid.setText(name);
			}
		}
	}
}

package com.osrsmarket.ledger;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.util.QuantityFormatter;

@Singleton
final class GeOfferChatbox
{
	private static final int LINK = 0x800000;
	private static final int HOVER = 0xFFFFFF;
	private static final int MUTED = 0xAA2222;

	private final Client client;
	private final OsrsMarketLedgerConfig config;

	private Widget line1;
	private Widget line2;
	private Widget hint;

	@Inject
	GeOfferChatbox(Client client, OsrsMarketLedgerConfig config)
	{
		this.client = client;
		this.config = config;
	}

	void sync(GeOfferInput.Kind kind, Integer wikiBuy, Integer wikiSell, int geLimit, int allQty)
	{
		if (!config.chatboxPriceLinks() || kind == GeOfferInput.Kind.NONE)
		{
			line1 = line2 = hint = null;
			return;
		}
		Widget parent = client.getWidget(InterfaceID.Chatbox.MES_LAYER);
		if (parent == null || parent.isHidden())
		{
			line1 = line2 = hint = null;
			return;
		}
		if (!live(line1, parent) || !live(line2, parent) || !live(hint, parent))
		{
			line1 = child(parent, WidgetTextAlignment.LEFT, WidgetPositionMode.ABSOLUTE_TOP, 6, 10);
			line2 = child(parent, WidgetTextAlignment.LEFT, WidgetPositionMode.ABSOLUTE_TOP, 20, 10);
			hint = child(parent, WidgetTextAlignment.CENTER, WidgetPositionMode.ABSOLUTE_BOTTOM, 6, 0);
		}
		if (kind == GeOfferInput.Kind.PRICE)
		{
			link(line1, wikiBuy, wikiBuy != null && wikiBuy > 0 ? "set wiki instant buy: " + gp(wikiBuy) : "", wikiBuy == null ? 0 : wikiBuy, "wiki instant buy not loaded yet");
			link(line2, wikiSell, wikiSell != null && wikiSell > 0 ? "set wiki instant sell: " + gp(wikiSell) : "", wikiSell == null ? 0 : wikiSell, "wiki instant sell not loaded yet");
			hint.setText("J wiki buy  ·  N wiki sell  ·  click a line to type it");
			hint.setTextColor(LINK);
			clearClick(hint);
			return;
		}
		link(line1, geLimit, geLimit > 0 ? "set GE limit: " + QuantityFormatter.formatNumber(geLimit) : "", geLimit, "this item has no GE limit");
		link(line2, allQty, allQty > 0 ? "set all: " + QuantityFormatter.formatNumber(allQty) : "", allQty, "no inventory / cash for all");
		hint.setText("L GE limit  ·  A all  ·  click a line to type it");
		hint.setTextColor(LINK);
		clearClick(hint);
	}

	private void link(Widget widget, Integer value, String okText, int typed, String missing)
	{
		if (value == null || value <= 0)
		{
			widget.setText(missing);
			widget.setTextColor(MUTED);
			clearClick(widget);
			return;
		}
		widget.setText(okText);
		widget.setTextColor(LINK);
		widget.setAction(0, "Set");
		widget.setOnOpListener((JavaScriptCallback) ev -> GeOfferInput.type(client, typed));
		widget.setOnMouseRepeatListener((JavaScriptCallback) ev -> widget.setTextColor(HOVER));
		widget.setOnMouseLeaveListener((JavaScriptCallback) ev -> widget.setTextColor(LINK));
	}

	private static void clearClick(Widget widget)
	{
		widget.setAction(0, "");
		widget.setOnOpListener((Object[]) null);
		widget.setOnMouseRepeatListener((Object[]) null);
		widget.setOnMouseLeaveListener((Object[]) null);
	}

	private static Widget child(Widget parent, int xAlign, int yMode, int y, int x)
	{
		Widget widget = parent.createChild(-1, WidgetType.TEXT);
		widget.setTextColor(LINK);
		widget.setFontId(FontID.VERDANA_11_BOLD);
		widget.setYPositionMode(yMode);
		widget.setOriginalX(x);
		widget.setOriginalY(y);
		widget.setOriginalHeight(16);
		widget.setXTextAlignment(xAlign);
		widget.setWidthMode(WidgetSizeMode.MINUS);
		widget.setHasListener(true);
		widget.revalidate();
		return widget;
	}

	private static boolean live(Widget widget, Widget parent)
	{
		if (widget == null || parent == null)
		{
			return false;
		}
		try
		{
			return widget.getParent() == parent;
		}
		catch (RuntimeException e)
		{
			return false;
		}
	}

	private static String gp(int n)
	{
		return QuantityFormatter.formatNumber(n) + " gp";
	}
}

package com.osrsmarket.ledger;

import java.awt.event.KeyEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.KeyListener;

@Singleton
final class GeOfferHotkeys implements KeyListener
{
	private final Client client;
	private final ClientThread clientThread;
	private final OsrsMarketLedgerConfig config;

	private volatile GeOfferInput.Kind kind = GeOfferInput.Kind.NONE;
	private volatile int wikiBuy;
	private volatile int wikiSell;
	private volatile int geLimit;
	private volatile int allQty;

	@Inject
	GeOfferHotkeys(Client client, ClientThread clientThread, OsrsMarketLedgerConfig config)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
	}

	void setContext(GeOfferInput.Kind kind, int wikiBuy, int wikiSell, int geLimit, int allQty)
	{
		this.kind = kind == null ? GeOfferInput.Kind.NONE : kind;
		this.wikiBuy = wikiBuy;
		this.wikiSell = wikiSell;
		this.geLimit = geLimit;
		this.allQty = allQty;
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		GeOfferInput.Kind open = kind;
		if (open == GeOfferInput.Kind.NONE)
		{
			return;
		}
		int value = 0;
		if (open == GeOfferInput.Kind.PRICE)
		{
			if (config.wikiBuyHotkey().matches(e))
			{
				value = wikiBuy;
			}
			else if (config.wikiSellHotkey().matches(e))
			{
				value = wikiSell;
			}
		}
		else if (open == GeOfferInput.Kind.QUANTITY)
		{
			if (config.geLimitHotkey().matches(e))
			{
				value = geLimit;
			}
			else if (config.allQtyHotkey().matches(e))
			{
				value = allQty;
			}
		}
		if (value <= 0)
		{
			return;
		}
		e.consume();
		int typed = value;
		clientThread.invoke(() -> GeOfferInput.type(client, typed));
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
	}
}

package com.osrsmarket.ledger;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;

final class GeOfferInput
{
	enum Kind
	{
		NONE,
		PRICE,
		QUANTITY
	}

	private GeOfferInput()
	{
	}

	static Kind kind(Client client)
	{
		Widget title = client.getWidget(InterfaceID.Chatbox.MES_TEXT);
		if (title == null || title.isHidden())
		{
			return Kind.NONE;
		}
		return kindFromTitle(title.getText());
	}

	static Kind kindFromTitle(String title)
	{
		if (title == null)
		{
			return Kind.NONE;
		}
		if (title.equals("Set a price for each item:"))
		{
			return Kind.PRICE;
		}
		if (title.equals("How many do you wish to buy?")
			|| title.equals("How many do you wish to sell?"))
		{
			return Kind.QUANTITY;
		}
		return Kind.NONE;
	}

	static boolean type(Client client, int value)
	{
		if (value <= 0 || kind(client) == Kind.NONE)
		{
			return false;
		}
		Widget input = client.getWidget(InterfaceID.Chatbox.MES_TEXT2);
		if (input != null)
		{
			input.setText(value + "*");
		}
		client.setVarcStrValue(VarClientID.MESLAYERINPUT, String.valueOf(value));
		return true;
	}
}

