	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.GE_OFFERS)
		{
			clientThread.invokeLater(this::refreshPanel);
		}
		if (!config.syncTradeHistory() || event.getGroupId() != InterfaceID.GE_HISTORY)
		{
			return;
		}
		beginHistorySync();
	}

