package com.osrsmarket.ledger;

/** Time-on-market for a GE slot. Times are epoch millis; 0 means unknown. */
final class SlotIdle
{
	static final long STALL_FRESH_MS = 10 * 60 * 1000L;
	static final long STALL_AFTER_FILL_MS = 15 * 60 * 1000L;

	private SlotIdle()
	{
	}

	static long idleMs(long now, long listedAt, long lastFillAt)
	{
		if (listedAt <= 0)
		{
			return 0;
		}
		long from = lastFillAt > listedAt ? lastFillAt : listedAt;
		return Math.max(0, now - from);
	}

	static int idleMinutes(long now, long listedAt, long lastFillAt)
	{
		return (int) (idleMs(now, listedAt, lastFillAt) / 60_000L);
	}

	static boolean stalled(long now, long listedAt, long lastFillAt, int qtyFilled, boolean listed)
	{
		if (!listed || listedAt <= 0)
		{
			return false;
		}
		long idle = idleMs(now, listedAt, lastFillAt);
		if (qtyFilled <= 0)
		{
			return idle >= STALL_FRESH_MS;
		}
		return lastFillAt > 0 && idle >= STALL_AFTER_FILL_MS;
	}

	static String label(long now, long listedAt, long lastFillAt, int qtyFilled, boolean listed)
	{
		if (!listed || listedAt <= 0)
		{
			return "";
		}
		long listedMs = Math.max(0, now - listedAt);
		boolean stall = stalled(now, listedAt, lastFillAt, qtyFilled, listed);
		if (lastFillAt > listedAt)
		{
			String fill = "fill " + compactDuration(now - lastFillAt) + " ago";
			return stall ? fill + " · stalled" : fill;
		}
		String listedFor = "listed " + compactDuration(listedMs);
		if (qtyFilled <= 0 && stall)
		{
			return listedFor + " · not moving";
		}
		return stall ? listedFor + " · stalled" : listedFor;
	}

	static String compactDuration(long ms)
	{
		long sec = Math.max(0, ms / 1000L);
		if (sec < 60)
		{
			return sec + "s";
		}
		long min = sec / 60;
		if (min < 60)
		{
			return min + "m";
		}
		long hr = min / 60;
		long rem = min % 60;
		return rem == 0 ? hr + "h" : hr + "h " + rem + "m";
	}
}

package com.osrsmarket.ledger;

/** Saved GE slot listing clock: item + price + qty identify the same offer. */
final class SlotListing
{
	final int itemId;
	final long price;
	final int qty;
	final long listedAt;
	final long lastFillAt;

	SlotListing(int itemId, long price, int qty, long listedAt, long lastFillAt)
	{
		this.itemId = itemId;
		this.price = price;
		this.qty = qty;
		this.listedAt = listedAt;
		this.lastFillAt = lastFillAt;
	}

	boolean sameOffer(int itemId, long price, int qty)
	{
		return this.itemId == itemId && this.price == price && this.qty == qty && listedAt > 0;
	}

	String encode()
	{
		return itemId + ":" + price + ":" + qty + ":" + listedAt + ":" + lastFillAt;
	}

	static SlotListing parse(String raw)
	{
		if (raw == null || raw.isEmpty())
		{
			return null;
		}
		String[] parts = raw.split(":");
		if (parts.length < 4)
		{
			return null;
		}
		try
		{
			int itemId = Integer.parseInt(parts[0]);
			long price = Long.parseLong(parts[1]);
			int qty = Integer.parseInt(parts[2]);
			long listedAt = Long.parseLong(parts[3]);
			long lastFillAt = parts.length > 4 ? Long.parseLong(parts[4]) : 0L;
			if (itemId <= 0 || listedAt <= 0)
			{
				return null;
			}
			return new SlotListing(itemId, price, qty, listedAt, lastFillAt);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	static String key(int slot)
	{
		return "listed." + slot;
	}
}

package com.osrsmarket.ledger;

import java.awt.Color;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.client.util.QuantityFormatter;

final class SlotMargin
{
	enum Health
	{
		GOOD(new Color(55, 240, 70), "On market"),
		WARN(new Color(230, 150, 30), "In spread"),
		BAD(new Color(230, 30, 30), "Update"),
		NEUTRAL(new Color(120, 120, 120), "");

		final Color color;
		final String label;

		Health(Color color, String label)
		{
			this.color = color;
			this.label = label;
		}
	}

	final Health health;
	final String tooltip;
	final String adjust;
	final Integer instantBuy;
	final Integer instantSell;
	final Long spreadAfterTax;
	final Long ifSellAtIb;
	final int avgCost;
	final int breakeven;
	final Long vsBook;

	private SlotMargin(
		Health health,
		String tooltip,
		String adjust,
		Integer instantBuy,
		Integer instantSell,
		Long spreadAfterTax,
		Long ifSellAtIb,
		int avgCost,
		int breakeven,
		Long vsBook)
	{
		this.health = health;
		this.tooltip = tooltip;
		this.adjust = adjust;
		this.instantBuy = instantBuy;
		this.instantSell = instantSell;
		this.spreadAfterTax = spreadAfterTax;
		this.ifSellAtIb = ifSellAtIb;
		this.avgCost = avgCost;
		this.breakeven = breakeven;
		this.vsBook = vsBook;
	}

	static SlotMargin empty()
	{
		return new SlotMargin(Health.NEUTRAL, "Empty slot", "", null, null, null, null, 0, 0, null);
	}

	static SlotMargin analyze(GrandExchangeOffer offer, WikiQuotes.Quote quote, int avgCost)
	{
		if (offer == null || offer.getItemId() <= 0 || offer.getState() == GrandExchangeOfferState.EMPTY)
		{
			return empty();
		}
		boolean buy = offer.getState() == GrandExchangeOfferState.BUYING
			|| offer.getState() == GrandExchangeOfferState.BOUGHT
			|| offer.getState() == GrandExchangeOfferState.CANCELLED_BUY;
		boolean sell = offer.getState() == GrandExchangeOfferState.SELLING
			|| offer.getState() == GrandExchangeOfferState.SOLD
			|| offer.getState() == GrandExchangeOfferState.CANCELLED_SELL;
		return analyze(
			buy,
			sell,
			offer.getPrice(),
			offer.getQuantitySold(),
			offer.getTotalQuantity(),
			quote,
			avgCost);
	}

	static SlotMargin analyze(
		boolean buy,
		boolean sell,
		long price,
		int qtySold,
		int qtyTotal,
		WikiQuotes.Quote quote,
		int avgCost)
	{
		Integer high = quote == null ? null : quote.high;
		Integer low = quote == null ? null : quote.low;
		Long spread = high != null && low != null ? Long.valueOf(GeTax.afterTax(high) - low) : null;
		Long ifSellAtIb = buy && high != null && price > 0 ? Long.valueOf(GeTax.afterTax(high) - price) : null;
		int breakeven = avgCost > 0 ? GeTax.breakeven(avgCost) : 0;
		Long vsBook = sell && avgCost > 0 && price > 0 ? Long.valueOf(GeTax.afterTax(price) - avgCost) : null;

		StringBuilder html = new StringBuilder("<html>");
		html.append(esc(buy ? "Buy" : sell ? "Sell" : "Offer"));
		if (qtyTotal > 0)
		{
			html.append(' ')
				.append(qtySold)
				.append(" / ")
				.append(qtyTotal);
		}
		if (price > 0)
		{
			html.append(" @ ").append(gp(price));
		}
		html.append("<br>");
		if (high != null)
		{
			html.append("Buy price (instant-buy): ").append(gp(high)).append("<br>");
		}
		if (low != null)
		{
			html.append("Sell price (instant-sell): ").append(gp(low)).append("<br>");
		}
		if (spread != null)
		{
			html.append("After-tax spread: ").append(signed(spread)).append("<br>");
		}

		Health health;
		String adjust;
		if (high == null || low == null)
		{
			health = Health.NEUTRAL;
			adjust = "No live wiki quote yet.";
		}
		else if (price <= 0)
		{
			health = Health.NEUTRAL;
			adjust = "Set a price to see margin.";
		}
		else if (buy)
		{
			html.append("If you sell at buy price: ").append(signed(ifSellAtIb)).append("/ea<br>");
			if (ifSellAtIb == null || ifSellAtIb <= 0 || price >= high)
			{
				health = Health.BAD;
				adjust = "Out of margin. Drop buy to " + gp(low) + " (sell price / buy edge).";
			}
			else if (price <= low)
			{
				health = Health.GOOD;
				adjust = "On the buy edge. Hold, or overbid to " + gp(low + 1) + " to front the queue.";
			}
			else
			{
				health = Health.WARN;
				adjust = "Above the buy edge. Drop to " + gp(low) + " for a patient buy, or keep bidding to fill faster.";
			}
		}
		else if (sell)
		{
			if (avgCost > 0)
			{
				html.append("Avg cost: ").append(gp(avgCost)).append("<br>");
				html.append("Breakeven: ").append(gp(breakeven)).append("<br>");
				html.append("Vs book: ").append(signed(vsBook)).append("/ea<br>");
			}
			boolean belowCost = avgCost > 0 && vsBook != null && vsBook < 0;
			if (belowCost || price <= low)
			{
				health = Health.BAD;
				adjust = belowCost
					? "Below breakeven " + gp(breakeven) + ". Raise or abort."
					: "At/under dump price (chart sell). Raise toward " + gp(high) + " (chart buy).";
			}
			else if (price >= high)
			{
				health = Health.GOOD;
				adjust = "On the sell edge. Hold, or undercut to " + gp(Math.max(1, high - 1)) + ".";
			}
			else
			{
				health = Health.WARN;
				adjust = "Under the sell edge. Raise to " + gp(high) + " to sit on the market.";
			}
		}
		else
		{
			health = Health.NEUTRAL;
			adjust = "";
		}

		html.append("<br>").append(esc(adjust)).append("<br>");
		html.append("<br>Green = on the edge (buy at sell / sell at buy)<br>");
		html.append("Yellow = inside the spread, not at the edge<br>");
		html.append("Red = off-market / out of margin — update the offer");
		html.append("</html>");
		return new SlotMargin(
			health,
			html.toString(),
			adjust,
			high,
			low,
			spread,
			ifSellAtIb,
			avgCost,
			breakeven,
			vsBook);
	}

	static String gp(long n)
	{
		return QuantityFormatter.formatNumber(n) + " gp";
	}

	static String signed(long n)
	{
		String body = QuantityFormatter.formatNumber(Math.abs(n)) + " gp";
		if (n > 0)
		{
			return "+" + body;
		}
		if (n < 0)
		{
			return "-" + body;
		}
		return body;
	}

	private static String esc(String s)
	{
		if (s == null)
		{
			return "";
		}
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.osrsmarket.ledger;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

@Slf4j
@Singleton
final class WikiQuotes
{
	private static final String LATEST = "https://prices.runescape.wiki/api/v1/osrs/latest";
	private static final long TTL_MS = 30_000;

	static final class Quote
	{
		final Integer high;
		final Integer low;

		Quote(Integer high, Integer low)
		{
			this.high = high;
			this.low = low;
		}
	}

	private final OkHttpClient http;
	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final Map<Integer, Quote> quotes = new ConcurrentHashMap<>();
	private final AtomicLong fetchedAt = new AtomicLong(0);
	private final AtomicBoolean inFlight = new AtomicBoolean(false);
	private volatile Runnable onUpdated;

	@Inject
	WikiQuotes(OkHttpClient http, Gson gson, ScheduledExecutorService executor)
	{
		this.http = http;
		this.gson = gson;
		this.executor = executor;
	}

	Quote get(int itemId)
	{
		return quotes.get(itemId);
	}

	void setOnUpdated(Runnable onUpdated)
	{
		this.onUpdated = onUpdated;
	}

	void refreshIfStale()
	{
		if (System.currentTimeMillis() - fetchedAt.get() < TTL_MS)
		{
			return;
		}
		if (!inFlight.compareAndSet(false, true))
		{
			return;
		}
		executor.execute(this::fetch);
	}

	private void fetch()
	{
		Request request = new Request.Builder()
			.url(LATEST)
			.header("User-Agent", "OSRS-Ledger/1.0")
			.header("Accept", "application/json")
			.build();
		try (Response response = http.newCall(request).execute())
		{
			if (!response.isSuccessful() || response.body() == null)
			{
				log.debug("Wiki latest HTTP {}", response.code());
				return;
			}
			JsonObject root = gson.fromJson(response.body().charStream(), JsonObject.class);
			if (root == null)
			{
				return;
			}
			JsonObject data = root.getAsJsonObject("data");
			if (data == null)
			{
				return;
			}
			Map<Integer, Quote> next = new ConcurrentHashMap<>();
			for (Map.Entry<String, JsonElement> e : data.entrySet())
			{
				int id;
				try
				{
					id = Integer.parseInt(e.getKey());
				}
				catch (NumberFormatException ex)
				{
					continue;
				}
				if (!e.getValue().isJsonObject())
				{
					continue;
				}
				JsonObject row = e.getValue().getAsJsonObject();
				next.put(id, new Quote(intOrNull(row, "high"), intOrNull(row, "low")));
			}
			quotes.clear();
			quotes.putAll(next);
			fetchedAt.set(System.currentTimeMillis());
			Runnable cb = onUpdated;
			if (cb != null)
			{
				cb.run();
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Wiki latest failed: {}", e.getMessage());
		}
		finally
		{
			inFlight.set(false);
		}
	}

	private static Integer intOrNull(JsonObject row, String key)
	{
		if (!row.has(key) || row.get(key).isJsonNull())
		{
			return null;
		}
		try
		{
			int n = row.get(key).getAsInt();
			return n > 0 ? n : null;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}
}

