package com.osrsmarket.ledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class SlotIdleTest
{
	@Test
	public void freshOfferIsNotStalled()
	{
		long listed = 1_000_000L;
		long now = listed + 3 * 60_000L;
		assertFalse(SlotIdle.stalled(now, listed, 0, 0, true));
		assertEquals("listed 3m", SlotIdle.label(now, listed, 0, 0, true));
	}

	@Test
	public void noFillsForTenMinutesIsNotMoving()
	{
		long listed = 1_000_000L;
		long now = listed + SlotIdle.STALL_FRESH_MS;
		assertTrue(SlotIdle.stalled(now, listed, 0, 0, true));
		assertEquals("listed 10m · not moving", SlotIdle.label(now, listed, 0, 0, true));
	}

	@Test
	public void fillResetsIdleUntilFifteenMinutes()
	{
		long listed = 1_000_000L;
		long fill = listed + 2 * 60_000L;
		long now = fill + 5 * 60_000L;
		assertFalse(SlotIdle.stalled(now, listed, fill, 4, true));
		assertEquals("fill 5m ago", SlotIdle.label(now, listed, fill, 4, true));
		long stalledAt = fill + SlotIdle.STALL_AFTER_FILL_MS;
		assertTrue(SlotIdle.stalled(stalledAt, listed, fill, 4, true));
		assertEquals("fill 15m ago · stalled", SlotIdle.label(stalledAt, listed, fill, 4, true));
	}

	@Test
	public void emptyOrUnlistedHasNoLabel()
	{
		assertEquals("", SlotIdle.label(10, 1, 0, 0, false));
		assertFalse(SlotIdle.stalled(10, 1, 0, 0, false));
	}
}

package com.osrsmarket.ledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class SlotListingTest
{
	@Test
	public void roundTrip()
	{
		SlotListing saved = new SlotListing(4151, 1000, 50, 1_700_000_000_000L, 1_700_000_100_000L);
		SlotListing parsed = SlotListing.parse(saved.encode());
		assertNotNull(parsed);
		assertTrue(parsed.sameOffer(4151, 1000, 50));
		assertEquals(saved.listedAt, parsed.listedAt);
		assertEquals(saved.lastFillAt, parsed.lastFillAt);
	}

	@Test
	public void differentOfferDoesNotMatch()
	{
		SlotListing saved = new SlotListing(4151, 1000, 50, 100L, 0L);
		assertFalse(saved.sameOffer(4151, 1001, 50));
		assertFalse(saved.sameOffer(4151, 1000, 49));
		assertFalse(saved.sameOffer(11802, 1000, 50));
	}

	@Test
	public void rejectsGarbage()
	{
		assertNull(SlotListing.parse(null));
		assertNull(SlotListing.parse(""));
		assertNull(SlotListing.parse("1:2:3"));
		assertNull(SlotListing.parse("nope"));
		assertNull(SlotListing.parse("0:1:1:100"));
	}

	@Test
	public void slotKeysAreStable()
	{
		assertEquals("listed.0", SlotListing.key(0));
		assertEquals("listed.7", SlotListing.key(7));
	}
}

package com.osrsmarket.ledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class SlotMarginTest
{
	@Test
	public void buyOnBuyEdgeSuggestsOverbid()
	{
		WikiQuotes.Quote quote = new WikiQuotes.Quote(19_342_268, 18_846_745);
		SlotMargin margin = SlotMargin.analyze(true, false, 18_705_000, 0, 2, quote, 0);
		assertEquals(SlotMargin.Health.GOOD, margin.health);
		assertEquals(Integer.valueOf(19_342_268), margin.instantBuy);
		assertEquals(Integer.valueOf(18_846_745), margin.instantSell);
		assertTrue(margin.adjust.contains("On the buy edge"));
		assertTrue(margin.adjust.contains("18,846,746"));
	}

	@Test
	public void buyAboveInstantBuyIsOutOfMargin()
	{
		WikiQuotes.Quote quote = new WikiQuotes.Quote(100, 90);
		SlotMargin margin = SlotMargin.analyze(true, false, 100, 0, 1, quote, 0);
		assertEquals(SlotMargin.Health.BAD, margin.health);
	}

	@Test
	public void taxCapsPastMaxCash()
	{
		assertEquals(5_000_000L, GeTax.tax(3_000_000_000L));
	}

	@Test
	public void sellOnSellEdgeSuggestsUndercut()
	{
		WikiQuotes.Quote quote = new WikiQuotes.Quote(100, 90);
		SlotMargin margin = SlotMargin.analyze(false, true, 100, 0, 1, quote, 0);
		assertEquals(SlotMargin.Health.GOOD, margin.health);
		assertTrue(margin.adjust.contains("On the sell edge"));
		assertTrue(margin.adjust.contains("99"));
	}
}
